using Microsoft.AspNetCore.Identity.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;

namespace ShipmentTracker.Data;

public class ApplicationDbContext(DbContextOptions<ApplicationDbContext> options) : IdentityDbContext<ApplicationUser>(options)
{
    public DbSet<ShipmentEntity> Shipments => Set<ShipmentEntity>();

    protected override void OnModelCreating(ModelBuilder builder)
    {
        base.OnModelCreating(builder);

        builder.Entity<ShipmentEntity>(e =>
        {
            e.HasIndex(s => s.TrackingNumber).IsUnique();
        });

        // Seed sample data
        builder.Entity<ShipmentEntity>().HasData(
            new ShipmentEntity { Id = 1, TrackingNumber = "TRK-001-2026", Origin = "New York, US", Destination = "London, UK", Status = ShipmentStatus.InTransit, ShippedDate = new DateTime(2026, 6, 20), EstimatedDelivery = new DateTime(2026, 6, 30), CustomerEmail = "customer1@example.com", Description = "Electronics - 2 pallets" },
            new ShipmentEntity { Id = 2, TrackingNumber = "TRK-002-2026", Origin = "Shanghai, CN", Destination = "Los Angeles, US", Status = ShipmentStatus.OutForDelivery, ShippedDate = new DateTime(2026, 6, 15), EstimatedDelivery = new DateTime(2026, 6, 28), CustomerEmail = "customer2@example.com", Description = "Textiles - 5 containers" },
            new ShipmentEntity { Id = 3, TrackingNumber = "TRK-003-2026", Origin = "Berlin, DE", Destination = "Tokyo, JP", Status = ShipmentStatus.Pending, ShippedDate = new DateTime(2026, 6, 25), EstimatedDelivery = new DateTime(2026, 7, 5), CustomerEmail = "customer3@example.com", Description = "Auto parts - 1 crate" },
            new ShipmentEntity { Id = 4, TrackingNumber = "TRK-004-2026", Origin = "São Paulo, BR", Destination = "Mumbai, IN", Status = ShipmentStatus.Delivered, ShippedDate = new DateTime(2026, 6, 10), EstimatedDelivery = new DateTime(2026, 6, 22), ActualDelivery = new DateTime(2026, 6, 21), CustomerEmail = "customer4@example.com", Description = "Coffee beans - 3 pallets" },
            new ShipmentEntity { Id = 5, TrackingNumber = "TRK-005-2026", Origin = "Sydney, AU", Destination = "Vancouver, CA", Status = ShipmentStatus.Delayed, ShippedDate = new DateTime(2026, 6, 18), EstimatedDelivery = new DateTime(2026, 7, 2), CustomerEmail = "customer5@example.com", Description = "Machinery - heavy freight" }
        );
    }
}

